import type { D1Database, KVNamespace } from "@cloudflare/workers-types";
import { updateShopTheme } from "../db/queries.js";

export interface ShopThemeConfig {
  primaryColor: string;
  accentColor: string;
  fontHeading: string;
  fontBody: string;
  tagline: string;
  heroHeadline: string;
  shortDescription: string;
  aestheticKeywords: string[];
}

interface ClaudeResponse {
  content: Array<{ type: string; text: string }>;
  error?: { message: string };
}

const THEME_KV_TTL = 60 * 60 * 24 * 30; // 30 days

/**
 * Generates a brand theme for a shop using Claude Sonnet.
 * Stores result in D1 (shops.ai_theme) and KV (shop:theme:{shopId}).
 */
export async function generateShopTheme(
  shopName: string,
  shopType: string,
  apiKey: string,
  shopId: string,
  db: D1Database,
  kv: KVNamespace
): Promise<ShopThemeConfig> {
  const shopTypeLabel = shopType.replace(/_/g, " ");

  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "x-api-key": apiKey,
      "anthropic-version": "2023-06-01",
    },
    body: JSON.stringify({
      model: "claude-sonnet-4-20250514",
      max_tokens: 1024,
      system: "You are a brand designer. Return ONLY valid JSON, no markdown, no explanation.",
      messages: [
        {
          role: "user",
          content:
            `Generate a brand config for a ${shopTypeLabel} called '${shopName}'. ` +
            `Return JSON with keys: primaryColor (hex), accentColor (hex), ` +
            `fontHeading (Google Font name), fontBody (Google Font name), ` +
            `tagline (short punchy tagline), heroHeadline (bold hero text), ` +
            `shortDescription (2 sentences), aestheticKeywords (array of 4-6 strings).`,
        },
      ],
    }),
  });

  if (!res.ok) {
    const errText = await res.text();
    throw new Error(`Claude API error ${res.status}: ${errText}`);
  }

  const data = (await res.json()) as ClaudeResponse;
  const rawText = data.content[0]?.text ?? "{}";

  let theme: ShopThemeConfig;
  try {
    theme = JSON.parse(rawText) as ShopThemeConfig;
  } catch {
    // Graceful fallback
    theme = {
      primaryColor: "#1a1a2e",
      accentColor: "#c9a84c",
      fontHeading: "Playfair Display",
      fontBody: "DM Sans",
      tagline: `Premium ${shopTypeLabel} experience.`,
      heroHeadline: `Welcome to ${shopName}`,
      shortDescription: `${shopName} offers premium ${shopTypeLabel} services with expert staff. Book your appointment online today.`,
      aestheticKeywords: ["luxury", "professional", "modern", "welcoming"],
    };
  }

  const themeJson = JSON.stringify(theme);

  // Persist to D1
  await updateShopTheme(db, shopId, themeJson);

  // Cache in KV (30-day TTL)
  await kv.put(`shop:theme:${shopId}`, themeJson, { expirationTtl: THEME_KV_TTL });

  return theme;
}
