// ─── Platform Users ───────────────────────────────────────────────────────────

export function getUserByEmail(db: D1Database, email: string) {
  return db
    .prepare("SELECT * FROM platform_users WHERE email = ? LIMIT 1")
    .bind(email)
    .first<DBUser>();
}

export function getUserById(db: D1Database, id: string) {
  return db
    .prepare("SELECT id, email, role, shop_id, created_at FROM platform_users WHERE id = ? LIMIT 1")
    .bind(id)
    .first<Omit<DBUser, "password_hash">>();
}

export function createUser(db: D1Database, user: {
  id: string;
  email: string;
  password_hash: string;
  role: string;
  shop_id?: string | null;
}) {
  return db
    .prepare(
      "INSERT INTO platform_users (id, email, password_hash, role, shop_id) VALUES (?, ?, ?, ?, ?)"
    )
    .bind(user.id, user.email, user.password_hash, user.role, user.shop_id ?? null)
    .run();
}

