export async function checkSlotConflict(
  db: D1Database,
  staffId: string,
  bookingDate: string,
  startTime: string,
  endTime: string
): Promise<boolean> {
  const row = await db
    .prepare(
      `SELECT 1 FROM bookings
       WHERE staff_id = ? AND booking_date = ?
         AND status NOT IN ('cancelled', 'no_show')
         AND start_time < ? AND end_time > ?
       LIMIT 1`
    )
    .bind(staffId, bookingDate, endTime, startTime)
    .first();
  return !!row;
}

